        "Në rastin e Gjermanisë, Letonisë ose ddo rajoni tjetër me kufij, ai përkthehet si shtet.",
        "Duhet të përkthehet si fshat ose tokë kur flitet për fshat ose tokë në vend të qytetit.",
        "Konteksti përcakton nëse e kemi fjalën për vendin, fshatin apo tokën."
