        "Kur bëhet fjalë për veshjet, passen zakonisht nënkupton rregullimin e madhësisë.",
        "Kur bëhet fjalë për ngjyrat dhe stilin, passen përfaqëson përputhjen.",
        "Një shprehje shumë e njohur është das passt. = Përputhet."
