        "Kur bëhet fjalë për ushqim dhe pije, probieren zakonisht do të thotë shijim.",
        "Do të thotë të provosh prova kur bëhet fjalë për një veprim, metodë ose gjë.",
        "Kjo nuk është e njëjtë me prüfen, që do të thotë kontroll më i plotë."
