      "explanation": [
        "Ideja kryesore: sicher do të thotë e përcaktuar si mbiemër, dhe patjetër/ndoshta si zarf.",
        "Bir yer, durum veya kişi hakkında konuştuğumuzda, sicher = güvenli (ein sicherer Ort = güvenli yer).",
        "Si konfirmim ose siguri në një fjali sicher = absolutisht/natyrisht (Das ist sicher wahr. = Absolutisht e vërtetë.).",
        "Elbette! ayrı bir cevap olarak elbette!/muhtemelen! anlamına gelir."
      ],
