        "Sie'nin esas anlamı: bir kadın.",
        "Zakonisht karakterizohet nga folja njëjës (-t).",
        "SIE në thelb do të thotë: disa njerëz.",
        "Genellikle şu şekilde karakterize edilir: çoğul bir fiil (-en).",
        "SIE në thelb do të thotë: adresë e sjellshme.",
        "Shpesh përshkruhet: domosdoshmërisht me kapital S.",
        "Rrethimi i vogël e shpreh atë kur folja është njëjës (Sie kocht = ai gatim)."
